\left\lVert \begin{pmatrix} 2 \\ 2 \end{pmatrix} \right\rVert
= \sqrt{\left\langle \begin{pmatrix} 2 \\ 2 \end{pmatrix}, \begin{pmatrix} 2 \\ 2 \end{pmatrix} \right\rangle}
= \sqrt{2^2 + 2^2}
= \sqrt{8}
\approx 2.83
\end{equation}\]

